<template><section class="panel" aria-labelledby="snapshot-history-title"><h2 id="snapshot-history-title">{{t('publicPricingAdmin.historyTitle')}}</h2><ul class="history"><li v-for="item in items" :key="item.guid"><div><strong>v{{item.version}}</strong> <el-tag v-if="item.reason==='upstream_safety'||item.systemGenerated" type="warning">{{t('publicPricingAdmin.systemGenerated')}}</el-tag><el-tag v-else-if="item.reason==='restore'">{{t('publicPricingAdmin.restored')}}</el-tag><p>{{item.createdAt}} · {{t('publicPricingAdmin.sourceRevision',{revision:item.sourceRevision})}}</p></div><el-button :disabled="busy||item.guid===currentGuid" @click="$emit('restore',item,$event)">{{t('publicPricingAdmin.restore')}}</el-button></li><li v-if="!items.length">{{t('publicPricingAdmin.emptyHistory')}}</li></ul></section></template>
<script setup>import{useI18n}from'@/composables/useI18n';defineProps({items:{type:Array,default:()=>[]},busy:Boolean,currentGuid:String});defineEmits(['restore']);const{t}=useI18n()</script>
<style scoped>.panel{background:var(--el-bg-color);border:1px solid var(--el-border-color);border-radius:16px;padding:20px}.history{list-style:none;padding:0}.history li{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--el-border-color)}.history p{margin:4px 0;color:var(--text-secondary)}@media(max-width:600px){.history li{align-items:flex-start;flex-direction:column}}</style>
